use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    /// Drop every item whose id is already present in the `seen` store.
    ///
    /// Only the parser-computed `id` is used as a key; the rest of each
    /// untrusted item is passed through unchanged, in its original order.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
